<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    name</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  as</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> productName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
